const request = $input.first().json;
const body = request.body ?? request;
const headers = request.headers ?? {};
const forwarded = headers['x-forwarded-for'] ?? headers['X-Forwarded-For'];
return [{
  json: {
    event: 'sweetwater_card_scan',
    source: body.source ?? 'direct',
    batch: body.batch ?? null,
    scanned_at: body.ts ? new Date(body.ts).toISOString() : new Date().toISOString(),
    received_at: new Date().toISOString(),
    referrer: body.referrer ?? null,
    user_agent: body.ua ?? headers['user-agent'] ?? null,
    ip: typeof forwarded === 'string' ? forwarded.split(',')[0].trim() : null
  }
}];
